function UICultivateAttributeNode:RefreshUI(basicConf, curAttr, additionAttr, isConversion)
    self.ImgIcon:LoadSprite(basicConf.icon)
    self.TxtName.text = basicConf.name
    self.basicConf = basicConf
    local attrNum = curAttr
    local isShowAddition = additionAttr ~= nil and checkNumber(additionAttr) ~= 0
    local sign = checkNumber(additionAttr) > 0 and "+" or "-"
    local curAttrNumText, additionAttrText
    if isConversion then
        curAttrNumText = tostring(attribute_format(isConversion, checkNumber(attrNum)))
        --isShowAddition = isShowAddition and math.floor(checkNumber(additionAttr)) > 0
        additionAttrText = isShowAddition and sign .. string.format("%s", attribute_format(isConversion, checkNumber(additionAttr))) or ""
    else
        curAttrNumText = tostring(attrNum)
        additionAttrText = isShowAddition and sign .. string.format("%s", additionAttr) or ""
    end
    self.isShowAddition = isShowAddition
    self.TxtNumber.text = curAttrNumText
    if self.TxtPlusNumber then
        KTool.SetActive(self.TxtPlusNumber.gameObject, isShowAddition)
        if isShowAddition then
            self.TxtPlusNumber.text = additionAttrText
        end
    end

    if self.STMP_PlusNumber then
        self.STMP_PlusNumber.Status = checkNumber(additionAttr) > 0 and 2 or 1
    end
end

function UICultivateAttributeNode:RefreshBgStatus(status)
    self.Bg.Status = status
end

function UICultivateAttributeNode:PlayUpgradeAni()
    if self.co then
        cs_coroutine.stop(self.co)
        if not isNull(self.effectGo) then
            KTool.SetActive(self.effectGo.gameObject, false)
        end
        self.co = nil
    end
    self.co = cs_coroutine.start(function()
        if self.effectGo == nil then
            self.effectGo = GameUtils.LoadBundleAsync(EffectPath, self.CultivateAttributeNode.gameObject, nil, true)
        else
            KTool.SetActive(self.effectGo.gameObject, true)
        end
        self.CultivateAttributeNode:Rebind()
        cs_coroutine.yield_return(self.CultivateAttributeNode:PlayAndWait(HashGo))
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        if not isNull(self.effectGo) then
            KTool.SetActive(self.effectGo.gameObject, false)
        end
        self.co = nil

    end)
end

function UICultivateAttributeNode:AddAttrClickEvent()
    if self.isAddEvent then
        return
    end
    self.isAddEvent = true
    SetButtonAction(self.BtnIcon.gameObject, function()
        -- GameUtils.ShowCommonTipsBoard(self.controller.gameObject, self.basicConf.name, self.basicConf.attributeDesc)
        GameUtils.ShowCommonTipsBoardAttribute(self.BtnIcon.gameObject, self.basicConf.name, self.basicConf.attributeDesc, false, true, 100)
    end)
end

